/** Las cuatro entradas EXPORT de L002R3, con la misma firma lógica. */
public interface RegistroContable {
    int cargaMov(byte[] datos);        // CARGAMOV1(DATOS)  EBCDIC ARRAY
    int enlace8d(byte[] datos);        // ENLACE_8D(DATOS)
    int cargaSaldos(byte[] datos);     // CARGASALDOS(DATOS)
    int controles(byte[] datos);       // CONTROLES(DATOS)
}

@Component
@RequiredArgsConstructor
public class RegistroContableLifecycle implements SmartLifecycle {

    private final EstadoLibreria estado;          // FIN_S408, FIN_S500, FUNCION_82/83, LLAMA_*
    private final CanalesDiarios canales;         // LEVANTA: arma los 10 canales
    private final AltaDisponibilidad ha;          // VERIFICA_HA (sólo sistema 500)
    private final ControlEventos control;         // PROC_CONTROL
    private final RegistroProperties props;
    private volatile boolean activo;

    @Override public void start() {
        estado.reinicia();                        // := FALSE de las banderas del bloque externo
        estado.levantaP015(true);
        canales.levanta();
        if (props.sistema() == 500) ha.verifica();
        control.arranca();                        // FREEZE(CONTROL, PROC_CONTROL)
        activo = true;
    }

    @Override public void stop() {                // BAJA al salir el último usuario
        control.detiene();
        canales.baja();
        activo = false;
    }

    @Override public boolean isRunning() { return activo; }
}

@Service
@RequiredArgsConstructor
public class RegistroContableService implements RegistroContable {

    private final CanalesDiarios canales;     // FEC_DIA[0:9], LOGS[0:9], DESS[0:9]...
    private final Map<Integer, FuncionRegistro> funciones;   // 1, 2, 11, 12, 21, 22, 31, 32, 50, 52, 95..98

    @Override
    public int cargaMov(byte[] datos) {
        MovimientoLog mov = MovimientoLog.de(datos);          // ALOG1 / ALOG2 / BLOG1
        int result = validaEncabezado(mov);                   // 1 sistema distinto, 16 formato > 3
        if (result != 0) return result;

        // El canal es el que tiene la misma fecha contable que el movimiento.
        OptionalInt canal = canales.porFecha(mov.fechaContable());
        boolean sinCanalPermitido = mov.funcion() == 95 || mov.funcion() == 96;
        if (canal.isEmpty() && !sinCanalPermitido) {
            return 4;                                         // RESULT := 4
        }
        var f = funciones.get(mov.funcion());
        if (f == null) return 2;                              // ELSE: RESULT := 2
        return f.ejecuta(mov, canal.orElse(-1));              // CARGAMEMORY, ELIMINA, INICIA...
    }
}

/** Cada rama del CASE es una estrategia; 1, 11, 12, 50 y 52 delegan en el mismo alta. */
public sealed interface FuncionRegistro
        permits Alta, BajaLogica, Inicia, Termina, EliminaPorProceso, EliminaPorAutorizacion,
                Reblockade, LiberaSbc, Ambienta, FinS408, PreFinal, Final {
    int ejecuta(MovimientoLog mov, int canal);
}

@Component
@RequiredArgsConstructor
public class CanalDiario {

    private static final int FUNCION_CENTINELA = 99;
    private final RegistroProperties props;
    private final ArchivoMovimientos movs;     // acceso por número de registro (75 palabras)
    private final OperadorConsola operador;    // LJ + ACCEPT

    /** ARMALOG: abre el MOV del día y devuelve el nivel del último registro válido. */
    public long arma(int canal, int fecDia /* AAAAMMDD */) {
        // ARC_MOV + fecha de 6 dígitos (FOR 6 DIGITS toma AAMMDD) + " ON " + PK_MOV + "."
        String titulo = "%s%06d ON %s.".formatted(props.arcMov(), fecDia % 1_000_000, props.pkMov());
        var archivo = movs.abre(canal, titulo);
        if (archivo.isEmpty()) return faltaArchivo(canal, titulo, fecDia);

        var f = archivo.get();
        RegistroLog header = f.lee(0);
        long sup = 0;
        if (header.funcion() != FUNCION_CENTINELA) {
            while (header.fecha() != fecDia) {                 // ERROR1: el header es de otro día
                operador.esperaCorreccion("ERROR1 LIB/REGISTRAS %03d, FECHA HEADER FILE/MOVTOS: %s FECHA CORRECTA: %08d"
                        .formatted(props.sistema(), header.fechaTexto(), fecDia));
                header = f.relee(0);
            }
            sup = f.ultimoRegistro();
        }
        // Búsqueda binaria del primer registro con función 99 (centinela).
        long inf = 0;
        while (inf != sup) {
            long mid = (sup - inf) / 2 + inf;                   // INTEGERT trunca
            if (f.lee(mid).funcion() == FUNCION_CENTINELA) sup = mid; else inf = mid;
            if (sup - inf == 1) sup = inf;
        }
        return sup;                                             // NIVLOG: próximo alta en sup + 1
    }
}

/** Rama ELSE de ARMALOG cuando el MOV no está residente. */
private long faltaArchivo(int canal, String titulo, int fecDia) {
    boolean requerido = nivelBase(canal) > 0
            && fecDia >= props.fechaProcesoBase()          // FEC_PRO_BASE
            && funcionActual() != 95;                      // 95 = ambientación
    if (!requerido) {
        return 0;                                          // NIVLOG := 0, el canal queda sin archivo
    }
    operador.esperaCorreccion("ERROR : FALTA ARCHIVO %s, FAVOR DE COPIARLO".formatted(titulo));
    return arma(canal, fecDia);                            // GO VERIFICA
}

@Component
@RequiredArgsConstructor
public final class Alta implements FuncionRegistro {

    private static final int HOLGURA_MINIMA = 300;            // registros libres antes de ampliar
    private final ValidadorMovimiento validador;              // DFVALIDA
    private final GrabaLog grabaLog;
    private final ControlProcesos procesos;                   // FEC_X_PROC[0:9,-1:99]
    private final CanalesDiarios canales;

    @Override
    @Transactional
    public int ejecuta(MovimientoLog mov, int canal) {
        int result = 0;
        if (mov.funcion() == 1) {
            result = validador.valida(mov);                   // sólo el alta se valida
        }
        // En ALGOL el IF de la línea 6516 termina en ';': GRABALOG no depende de la función.
        if (result == 0) {
            grabaLog.graba(canal, mov);
        }
        if (mov.funcion() == 1) {
            procesos.registraPrimeraAutorizacion(canal, mov.tipoProceso(), mov.autorizacion());
        }
        canales.ampliaSiHaceFalta(canal, TipoArchivo.MOV, HOLGURA_MINIMA, 75);
        canales.ampliaSiHaceFalta(canal, TipoArchivo.DES, HOLGURA_MINIMA, 90);
        // CBII y CDIR (210 palabras, 2000 registros por ampliación) sólo para el sistema 500.
        return result;
    }
}

@Component
@RequiredArgsConstructor
public class GrabaLog {

    private final CanalesDiarios canales;
    private final RegistroProperties props;

    public void graba(int canal, MovimientoLog mov) {
        var c = canales.get(canal);
        RegistroLog reg = RegistroLog.de(mov, /* apuntadorDesc */ 0, /* status */ 1);
        c.mov().escribe(c.nivelLog() + 1, reg);                // WRITE(LOG[NIVLOG + 1],75,BLOG)
        c.incrementaNivelLog();                                // NIVLOG := * + 1

        if (props.sistema() == 500 && (mov.funcion() == 50 || mov.funcion() == 52)) {
            MovimientoLog copia = (mov.funcion() == 52)
                    ? mov.conFuncion(1).conStatus(1)           // 52 se reescribe como alta con status 1
                    : mov;
            c.cdir().escribe(c.nivelCd(), copia);              // WRITE(AR_CD[NIV_CD],210,CD_LOG)
            c.cbii().escribe(c.nivelCb(), copia);              // WRITE(AR_CB[NIV_CB],210,CD_LOG)
            c.incrementaNivelCd();
            c.incrementaNivelCb();
        }
    }
}

/** Funciones 11 y 12: hoy sólo graban el movimiento; la sincronización con L001 está apagada. */
@Component
@RequiredArgsConstructor
public final class Inicia implements FuncionRegistro {

    private final Alta alta;
    private final SincronizacionNiveles sincronizacion;   // ACTNIVEL -> CONSISDIA de L001
    private final RegistroProperties props;

    @Override
    public int ejecuta(MovimientoLog mov, int canal) {
        int r = alta.ejecuta(mov, canal);                 // CARGAMEMORY
        if (props.sincronizaNivelesL001()) {              // %  ACTNIVEL;  (comentado)
            sincronizacion.actualiza(canal);
        }
        return r;
    }
}
