@Component
@RequiredArgsConstructor
public class ControlEventos {

    public enum Evento { TIMEOUT, HI_CONSOLA, BLOCK_LLENO, LEVANTA_PASOS,
                         INICIA_DIA, RESET_EVE, AMBIENTA }

    private final BlockingQueue<Evento> eventos = new LinkedBlockingQueue<>();
    private final ConsumidoresLibreria usuarios;          // MYSELF.LIBRARYUSERS
    private final EstadoLibreria estado;
    private final CanalesDiarios canales;
    private final RegistroProperties props;

    void ciclo() throws InterruptedException {
        while (usuarios.activos() > 0) {
            if (props.sistema() == 500 && estado.finS408() && estado.finS500()
                    && estado.funcion82() && estado.funcion83()) {
                estado.ejecutaP169();
                estado.limpiaBanderasP169();              // las cuatro banderas a FALSE
            }
            // WAITANDRESET((30), ...): el primer evento que ocurra o 30 segundos.
            Evento e = Optional.ofNullable(eventos.poll(props.timeoutSegundos(), SECONDS))
                               .orElse(Evento.TIMEOUT);
            switch (e) {
                case TIMEOUT -> {
                    if (estado.regXBlockD() > 0 || estado.regXBlockDx() > 0) {
                        estado.limpiaRegXBlock();
                        canales.cierraBloquesDesde(props.fechaProcesoBase());   // FEC_DIA >= FEC_PRO_BASE
                    }
                }
                case BLOCK_LLENO   -> bloqueLleno();
                case LEVANTA_PASOS -> levantaPasos();
                case INICIA_DIA    -> esperaFinDia();
                case RESET_EVE     -> { }                     // sólo reinicia el temporizador
                case AMBIENTA      -> ambienta();
                case HI_CONSOLA    -> comandoConsola();
            }
        }
        // MYSELF.STATUS := VALUE(GOINGAWAY); para 500: DELINKLIBRARY(S151L012)
    }
}

private int nBlockLleno;                       // N_BLOCK_LLENO

/** Evento 3. Reproduce el comportamiento actual, incluida la condición de reinicio. */
private void bloqueLleno() {
    nBlockLleno++;
    if (nBlockLleno == props.bloquesParaCierre()) {         // 20
        if (estado.regXBlockDx() > 0) {
            estado.limpiaRegXBlockDx();
            canales.cierraBloquesPosterioresA(props.fechaProceso());   // FEC_DIA > FECPROC
            nBlockLleno = 0;
        } else {
            // En el fuente el contador NO se reinicia aquí: pasa a 21 y la condición = 20
            // no vuelve a cumplirse. Se registra para que el SME decida si se corrige.
            log.warn("N_BLOCK_LLENO llegó a {} sin REG_X_BLOCK_DX; el cierre por bloque queda inactivo",
                     nBlockLleno);
        }
    }
}

    /** Evento 4. */
    private void levantaPasos() {
        estado.levantaP015(false);
        int copia = estado.indCopia();                            // IND_COPIA
        if (estado.activaP015() && canales.nivelLog(copia) > 0
                && estado.statusP015(copia) < 1) {
            lanzador.lanza(Paso.P015, copia);                     // EXTERNO_P015
            estado.activaP015(false);
        }
        if (estado.activaP016() && canales.nivelLog(copia) > 0
                && estado.statusP016(copia) < 1
                && LocalTime.now(reloj).isBefore(props.limiteP016())) {   // HORA < 200000
            lanzador.lanza(Paso.P016, copia);                     // EXTERNO_P016
            estado.activaP016(false);
        }
        estado.levantaP015(true);
    }

    /** Evento 5: no se acepta otro evento hasta que alguien señale FIN_DIA. */
    private void esperaFinDia() throws InterruptedException {
        finDia.acquire();                                         // WAITANDRESET(FIN_DIA)
    }

