/** Evento 7, primera parte. El arranque del WFL S151LOTE se delega a AmbientacionLauncher. */
private void ambienta() throws InterruptedException {
    for (int canal = 0; canal <= 9; canal++) {
        if (estado.statusP015(canal) > 0) consola.envia("%07d HI 4".formatted(estado.mixP015(canal)));
        if (estado.statusP016(canal) > 0) consola.envia("%07d HI 4".formatted(estado.mixP016(canal)));
    }
    Thread.sleep(props.esperaDetencion().toMillis());        // WAIT((2))
    for (int canal = 0; canal <= 9; canal++) canales.cierra(canal);   // CIERRALOG
    errores.cierra();                                         // CLOSE (ERRORES1,LOCK)
    estado.levantaP015(false);
    estado.activaP015(false);
    estado.activaP016(false);
    ambientacion.lanzaLote(props.sistema());                  // DAME_TIT("S151LOTE") + ZIP
    finAmbienta.release();                                    // CAUSE(FIN_AMBIENTA)
}
